  "error.sign_up_expired": "That took too long. Ask for a new code and try again.",
  "cli.usage": "openpadel: set up and check this club's {product}.\n  openpadel setup plan [club.yaml]    what setting the club up from the file would change (changes nothing)\n  openpadel setup apply [club.yaml]   make those changes; run it again after editing the file\n  openpadel import members <file.csv> [--apply]   members from a spreadsheet (a preview unless --apply)\n  openpadel doctor                    check that everything works, with the next step when it doesn't\n  openpadel reset-sign-in <email>     start someone's second sign-in step over (a lost phone, an owner locked out)\n  openpadel backup                    tonight's backup now: the dump and its manifest, and the offsite copy if set up\n  openpadel offsite                   what's kept offsite\n  openpadel restore <file|offsite:latest> --yes   replace the database with a backup, or with a club's export (sudo, on a one-server install)\n  openpadel export [--out=<folder>]   everything the club needs to run somewhere else, in one file sealed with a passphrase you type\n  openpadel read-only on|off|status   the host's switch: everyone signs in and downloads their data; nothing new is booked or charged\n  openpadel moved on [--to=<url>] | off | status   the club runs elsewhere now: this server sends members nothing; before an export\n  openpadel leaving on --date=YYYY-MM-DD [--kept-days=N] [--email-domain=<domain> [--email-domain-host]] | off | status   the day the club's {product} ends; the owner is told to download everything first, and what becomes of the email domain\n  openpadel held [send|drop] --yes      after a club's export is restored here: what the old server may have sent already, held until you say\n  openpadel pitr status               how far back the point-in-time archive reaches, and whether it keeps up\n  sudo openpadel restore --to=\"YYYY-MM-DD HH:MM\" --yes   the database as it was at that minute (club time), from the archive\n  openpadel restore-test              restore the newest backup into a scratch database and check it\n  openpadel rotate-key                seal every secret with KUMI_SECRET_KEY (the old key in KUMI_SECRET_KEY_PREVIOUS)\n  openpadel texting plan|apply|status [club.yaml]   register the club's texting with US carriers through its Twilio account (toll-free)\n  openpadel usage [--month=YYYY-MM]   what AI, texts and email cost the club this month (or that one), against its cap\n  sudo openpadel update <release.tar> | sudo openpadel rollback --yes | sudo openpadel releases   updating, on a one-server install\nAdd --json for output an agent can read, and --lang=es for Spanish.",
  "cli.usage_club": "On any computer: openpadel login <the club's address>, then openpadel help for the club's commands.",
  "cli.club_usage": "openpadel: the club's commands, from any computer.\n  openpadel login <address>          sign in to a club (its staff or members' app address): the browser opens, or --device gives a link and a code to allow from your phone (--no-wait to finish later)\n  openpadel whoami                   who you are there, your roles, and what the spending limit leaves this week\n  openpadel clubs | openpadel use <address>   the clubs signed in to here, and which one commands go to (or --club <address> on any command)\n  openpadel logout                   sign out here and end the connection at the club\n  openpadel <read> [flags]           read what the apps show (below)\n  openpadel <thing> <change> [flags] shows the change's preview and changes nothing (exit code 10)\n  openpadel confirm <run_id>         do a change you previewed, or run the command again with --yes\n  openpadel help <command>           its flags and an example; openpadel schema <command> for its JSON schema\nEvery command takes --json (one JSON object a line), --lang=es and --club. Names work where ids do (--person \"Maria Lopez\"), and a time without a zone is on the club's clock. On the club's server, openpadel doctor, setup, backup and the rest are there too (openpadel with nothing after it lists them).",
